;; --------------------------------------------
;; Sprite lookup tables
;; --------------------------------------------

; Head sprites by direction (0=up, 1=right, 2=down, 3=left)
spr_head_table:
        DW spr_head_up
        DW spr_head_right
        DW spr_head_down
        DW spr_head_left

; Tail sprites by direction
; When body segment moves in direction X, tail base connects FROM that direction
; So if body moves RIGHT, tail base is on LEFT side (use tail_left sprite)
spr_tail_table:
        DW spr_tail_up      ; DIR_UP=0: body moves up, tail connects from below
        DW spr_tail_left    ; DIR_RIGHT=1: body moves right, tail connects from left
        DW spr_tail_down    ; DIR_DOWN=2: body moves down, tail connects from above
        DW spr_tail_right   ; DIR_LEFT=3: body moves left, tail connects from right

; Corner sprites - indexed by (from_dir * 4 + to_dir)
; Swapped pairs: using dir_out*4+dir_in logic
spr_corner_table:
        ; from UP (0): 
        DW spr_body_v       ; 0->0 invalid
        DW spr_corner_lu    ; 0->1 = LU (was 1->0)
        DW spr_body_v       ; 0->2 invalid
        DW spr_corner_ru    ; 0->3 = UR (was 3->0)
        ; from RIGHT (1):
        DW spr_corner_rd    ; 1->0 = RD (was 0->1)
        DW spr_body_h       ; 1->1 invalid
        DW spr_corner_ru    ; 1->2 = UR (was 2->1)
        DW spr_body_h       ; 1->3 invalid
        ; from DOWN (2):
        DW spr_body_v       ; 2->0 invalid
        DW spr_corner_ld    ; 2->1 = DL (was 1->2)
        DW spr_body_v       ; 2->2 invalid
        DW spr_corner_rd    ; 2->3 = RD (was 3->2)
        ; from LEFT (3):
        DW spr_corner_ld    ; 3->0 = DL (was 0->3)
        DW spr_body_h       ; 3->1 invalid
        DW spr_corner_lu    ; 3->2 = LU (was 2->3)
        DW spr_body_h       ; 3->3 invalid
